class Solution {
public:
    int countTriplets(vector<int>& nums) {
        const int FULL = 1 << 16;
        vector<int> f(FULL, 0);
        int n = nums.size();
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                ++f[nums[i] & nums[j]];
        for (int b = 0; b < 16; ++b)
            for (int mask = 0; mask < FULL; ++mask)
                if (mask & (1 << b))
                    f[mask] += f[mask ^ (1 << b)];
        long long ans = 0;
        for (int x : nums)
            ans += f[(~x) & 0xFFFF];
        return (int)ans;
    }
};
